        expect(result.data.includeFinancialImpact).toBe(true); // default
      }
    });

    it('should require partyRole', () => {
      const input = {
        document: 'Contract text',
      };

      const result = RiskAssessInputSchema.safeParse(input);
      expect(result.success).toBe(false);
